 1	<!doctype html>
 2	<html lang="ru">
 3	<head>
 4	  <meta charset="utf-8">
 5	  <meta name="viewport" content="width=device-width, initial-scale=1">
 6	  <title>{% block title %}Игры Metacritic{% endblock %}</title>
 7	  <link rel="stylesheet" href="/static/style.css?v={{ static_version }}">
 8	  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='8' fill='%232f5bea'/%3E%3Ctext x='16' y='22' font-size='16' font-family='Arial' font-weight='700' fill='white' text-anchor='middle'%3EMC%3C/text%3E%3C/svg%3E">
 9	</head>
10	<body data-tz="{{ tz_name }}">
11	  <header class="topbar">
12	    <div class="wrap">
13	      <a class="brand" href="/"><span class="brand-mark">MC</span><span>Игры <span class="full">Metacritic: дайджест</span></span></a>
14	      <nav class="nav">
15	        <a href="/" class="{% if request.url.path == '/' or request.url.path.startswith('/game') %}active{% endif %}">Игры</a>
16	        <a href="/monitor" class="{% if request.url.path == '/monitor' %}active{% endif %}">Мониторинг</a>
17	      </nav>
18	    </div>
19	  </header>
20	  <main>
21	    <div class="wrap">
22	      {% block content %}{% endblock %}
23	    </div>
24	  </main>
25	  <footer>
26	    <div class="wrap">Данные: Metacritic (раздел Games) и YouTube. Резюме отзывов и заключения по летсплеям генерирует LLM; если она недоступна, показывается автоматическая выборка цитат. Время в часовом поясе {{ tz_name }}.</div>
27	  </footer>
28	  <script src="/static/app.js?v={{ static_version }}"></script>
29	</body>
30	</html>
 1	{% macro meta_badge(score, size='') -%}
 2	<span class="score {{ score|meta_class }} {{ size }}" title="Metascore">{{ score if score is not none else '—' }}</span>
 3	{%- endmacro %}
 4	{% macro user_badge(score, size='') -%}
 5	<span class="score user {{ score|user_class }} {{ size }}" title="Userscore">{{ score|user_fmt }}</span>
 6	{%- endmacro %}
 7	{% macro cover(url, title) -%}
 8	<div class="cover">
 9	  {% if url|url %}<img src="{{ url|url }}" alt="{{ title }}" loading="lazy" referrerpolicy="no-referrer">{% else %}<div class="noimg">нет обложки</div>{% endif %}
10	</div>
11	{%- endmacro %}
12	{% macro method_badge(method) -%}
13	{% set m = method or 'none' %}
14	<span class="badge {% if m.startswith('llm') %}llm{% elif m == 'none' %}{% else %}warn{% endif %}">{{ m|method }}</span>
15	{%- endmacro %}
 1	{% extends "base.html" %}
 2	{% from "_macros.html" import meta_badge, user_badge, cover %}
 3	{% block title %}Игры Metacritic{% endblock %}
 4	{% block content %}
 5	<div class="page-head">
 6	  <div>
 7	    <h1>Новые игры с Metacritic</h1>
 8	    <p class="muted">В базе {{ games_in_db }} {{ games_in_db|plural('игра', 'игры', 'игр') }}. Сервис раз в {{ interval_label }} забирает до {{ batch_size }} новых игр и обновляет уже известные.</p>
 9	  </div>
10	  <a class="btn ghost" href="/monitor">Мониторинг{% if running %} · идёт обработка{% endif %}</a>
11	</div>
12	
13	<form class="card filters" method="get" action="/" id="filters">
14	  <input class="q" type="search" name="q" value="{{ q }}" placeholder="Поиск по названию" aria-label="Поиск по названию">
15	  <select name="platform" aria-label="Платформа" data-autosubmit>
16	    <option value="">Все платформы</option>
17	    {% for p in platforms %}
18	    <option value="{{ p.name }}" {% if p.name == platform %}selected{% endif %}>{{ p.name }} ({{ p.games }})</option>
19	    {% endfor %}
20	  </select>
21	  <select name="sort" aria-label="Сортировка" data-autosubmit>
22	    {% for key, label in sort_labels.items() %}
23	    <option value="{{ key }}" {% if key == sort %}selected{% endif %}>{{ label }}</option>
24	    {% endfor %}
25	  </select>
26	  <button class="btn" type="submit">Найти</button>
27	</form>
28	
29	<div class="filter-meta">
30	  <span class="muted small">Найдено: {{ total }}{% if platform %} · оценки показаны для платформы {{ platform }}{% endif %}</span>
31	  {% if q or platform or sort != 'date_desc' %}<a class="small" href="/">Сбросить фильтры</a>{% endif %}
32	</div>
33	
34	{% if games %}
35	<div class="grid">
36	  {% for g in games %}
37	  <a class="card game-tile" href="/game/{{ g.slug|urlencode }}">
38	    {{ cover(g.cover_url, g.title) }}
39	    <div class="tile-body">
40	      <div class="tile-title">{{ g.title }}</div>
41	      <div class="tile-meta">{{ g.release_date|date_ru }}{% if g.developers %} · {{ g.developers[0] }}{% endif %}</div>
42	      <div class="chips">
43	        {% for p in g.platforms[:5] %}<span class="chip {% if p.name == platform %}accent{% endif %}" title="{{ p.name }}">{{ p.short }}</span>{% endfor %}
44	        {% if g.platforms|length > 5 %}<span class="chip">+{{ g.platforms|length - 5 }}</span>{% endif %}
45	      </div>
46	      <div class="scores">
47	        {{ meta_badge(g.score_meta) }}<span class="score-label">Meta<br>score</span>
48	        {{ user_badge(g.score_user) }}<span class="score-label">User<br>score</span>
49	      </div>
50	    </div>
51	  </a>
52	  {% endfor %}
53	</div>
54	{% if pages > 1 %}
55	<nav class="pager">
56	  {% if page > 1 %}<a href="{{ page_url(page - 1) }}">← Назад</a>{% endif %}
57	  {% for n in range(1, pages + 1) %}
58	    {% if n == page %}<span class="current">{{ n }}</span>
59	    {% elif n == 1 or n == pages or (n - page)|abs <= 2 %}<a href="{{ page_url(n) }}">{{ n }}</a>
60	    {% elif (n - page)|abs == 3 %}<span>…</span>{% endif %}
61	  {% endfor %}
62	  {% if page < pages %}<a href="{{ page_url(page + 1) }}">Вперёд →</a>{% endif %}
63	</nav>
64	{% endif %}
65	{% else %}
66	<div class="card empty">
67	  {% if games_in_db == 0 %}
68	  <h2>Игр пока нет</h2>
69	  <p class="muted">Первая обработка запускается автоматически вскоре после старта сервиса. Её ход видно на странице мониторинга, там же можно запустить обработку вручную.</p>
70	  <a class="btn" href="/monitor">Открыть мониторинг</a>
71	  {% else %}
72	  <h2>Ничего не найдено</h2>
73	  <p class="muted">Попробуйте изменить запрос или выбрать другую платформу.</p>
74	  <a class="btn ghost" href="/">Сбросить фильтры</a>
75	  {% endif %}
76	</div>
77	{% endif %}
78	{% endblock %}

  1	{% extends "base.html" %}
  2	{% from "_macros.html" import meta_badge, user_badge, cover, method_badge %}
  3	{% block title %}{{ g.title }} · Игры Metacritic{% endblock %}
  4	{% block content %}
  5	<p class="small"><a href="/">← Все игры</a></p>
  6	
  7	<section class="card hero">
  8	  {{ cover(g.cover_url, g.title) }}
  9	  <div class="hero-info">
 10	    <div>
 11	      <h1>{{ g.title }}</h1>
 12	      <div class="chips">
 13	        {% for genre in g.genres or [] %}<span class="chip">{{ genre }}</span>{% endfor %}
 14	        {% for fr in g.franchises or [] %}<span class="chip accent">{{ fr }}</span>{% endfor %}
 15	      </div>
 16	    </div>
 17	    <div class="hero-scores">
 18	      <div class="score-box">{{ meta_badge(g.metascore, 'lg') }}<div><strong>Metascore</strong><div class="muted small">{{ g.lead_platform or 'ведущая платформа' }}{% if g.critic_total %}, {{ g.critic_total }} {{ g.critic_total|plural('рецензия', 'рецензии', 'рецензий') }}{% endif %}</div></div></div>
 19	      <div class="score-box">{{ user_badge(g.userscore, 'lg') }}<div><strong>Userscore</strong><div class="muted small">{{ g.lead_platform or 'ведущая платформа' }}</div></div></div>
 20	    </div>
 21	    <dl class="facts">
 22	      <dt>Разработчик</dt><dd>{{ (g.developers or [])|join(', ') or '—' }}</dd>
 23	      <dt>Издатель</dt><dd>{{ (g.publishers or [])|join(', ') or '—' }}</dd>
 24	      <dt>Дата выхода</dt><dd>{{ g.release_date|date_ru }}</dd>
 25	      {% if g.rating %}<dt>Рейтинг ESRB</dt><dd>{{ g.rating }}</dd>{% endif %}
 26	      <dt>Платформы</dt><dd>{{ g.platforms|map(attribute='name')|join(', ') or '—' }}</dd>
 27	    </dl>
 28	    <div class="actions">
 29	      <a class="btn" href="{{ g.metacritic_url }}" target="_blank" rel="noopener noreferrer">Открыть на Metacritic</a>
 30	      {% if g.video %}<a class="btn ghost" href="{{ g.video.url|url }}" target="_blank" rel="noopener noreferrer">Трейлер{% if g.video.source == 'youtube' %} (YouTube){% endif %}</a>{% endif %}
 31	    </div>
 32	  </div>
 33	</section>
 34	
 35	<section class="section card pad">
 36	  <h2>Оценки по платформам</h2>
 37	  <div class="table-scroll">
 38	    <table>
 39	      <thead><tr><th>Платформа</th><th>Metascore</th><th>Userscore</th><th>Релиз</th></tr></thead>
 40	      <tbody>
 41	        {% for p in g.platforms %}
 42	        <tr>
 43	          <td><strong>{{ p.name }}</strong> <span class="chip">{{ p.short }}</span>{% if p.is_lead %} <span class="badge">ведущая</span>{% endif %}</td>
 44	          <td><div class="cell-score">{{ meta_badge(p.metascore) }}<span class="muted small">{% if p.critic_count %}{{ p.critic_count }} рец.{% else %}нет рецензий{% endif %}</span></div></td>
 45	          <td><div class="cell-score">{{ user_badge(p.userscore) }}<span class="muted small">{% if p.user_count %}{{ p.user_count|num }} {{ p.user_count|plural('оценка', 'оценки', 'оценок') }}{% else %}нет оценок{% endif %}</span></div></td>
 46	          <td class="muted">{{ p.release_date|date_ru }}</td>
 47	        </tr>
 48	        {% endfor %}
 49	      </tbody>
 50	    </table>
 51	  </div>
 52	</section>
 53	
 54	<section class="section card pad">
 55	  <h2>Описание</h2>
 56	  {% if g.description %}<p class="desc">{{ g.description }}</p>{% else %}<p class="muted">Описания на Metacritic нет.</p>{% endif %}
 57	  {% set v = g.video %}
 58	  {% if v and v.embed_url|url %}
 59	  <details>
 60	    <summary>Смотреть трейлер{% if v.title %}: {{ v.title }}{% endif %}</summary>
 61	    <div class="embed"><iframe src="{{ v.embed_url|url }}" title="{{ v.title or 'Трейлер' }}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>
 62	  </details>
 63	  <p class="small muted video-source">Ссылка на видео: <a href="{{ v.url|url }}" target="_blank" rel="noopener noreferrer">{{ v.url }}</a>{% if v.manifest_url|url %} · <a href="{{ v.manifest_url|url }}" target="_blank" rel="noopener noreferrer">HLS</a>{% endif %}
 64	    {% if v.source == 'youtube' %}<br>На Metacritic у этой игры видео нет, поэтому показан самый подходящий трейлер с YouTube{% if v.channel %} (канал {{ v.channel }}{% if v.views %}, {{ v.views|num }} {{ v.views|plural('просмотр', 'просмотра', 'просмотров') }}{% endif %}){% endif %}.{% endif %}</p>
 65	  {% else %}
 66	  <p class="small muted">Видео для этой игры нет ни на Metacritic, ни среди трейлеров на YouTube.</p>
 67	  {% endif %}
 68	</section>
 69	
 70	<div class="section two-col">
 71	  {% for kind, s, reviews, title in [('critic', g.critic_summary, g.critic_reviews, 'Что говорят критики'), ('user', g.user_summary, g.user_reviews, 'Что говорят игроки')] %}
 72	  <section class="card pad summary">
 73	    <h2>{{ title }}</h2>
 74	    {% if s and s.method != 'none' %}
 75	      {% if s.verdict %}<p class="verdict">{{ s.verdict }}</p>{% endif %}
 76	      {% if s.likes %}<h3>Нравится</h3><ul class="points likes">{% for x in s.likes %}<li>{{ x }}</li>{% endfor %}</ul>{% endif %}
 77	      {% if s.dislikes %}<h3>Не нравится</h3><ul class="points dislikes">{% for x in s.dislikes %}<li>{{ x }}</li>{% endfor %}</ul>
 78	      {% else %}<h3>Не нравится</h3><p class="muted small">Заметных претензий в отзывах нет.</p>{% endif %}
 79	      <div class="method">{{ method_badge(s.method) }} по {{ s.sample_size }} {{ s.sample_size|plural('отзыву', 'отзывам', 'отзывам') }} из {{ s.review_count }} · обновлено {{ s.updated_at|dt }}{% if s.note %}<br>{{ s.note }}{% endif %}</div>
 80	    {% elif s %}
 81	      <p class="muted">{{ s.verdict or 'Отзывов пока нет.' }}</p>
 82	    {% else %}
 83	      <p class="muted">Резюме ещё не построено.</p>
 84	    {% endif %}
 85	    {% if reviews %}
 86	    <details>
 87	      <summary>Исходные отзывы ({{ reviews|length }})</summary>
 88	      <ul class="quotes">
 89	        {% for r in reviews %}
 90	        <li class="{{ r.sentiment }}"><strong>{% if r.score is not none %}{{ r.score|int if kind == 'critic' else r.score }}{% else %}без оценки{% endif %}</strong>
 91	          · {% if r.url|url %}<a href="{{ r.url|url }}" target="_blank" rel="noopener noreferrer">{{ r.author or 'рецензия' }}</a>{% else %}{{ r.author or 'аноним' }}{% endif %}{% if r.platform %} · {{ r.platform }}{% endif %}<br>{{ r.quote }}</li>
 92	        {% endfor %}
 93	      </ul>
 94	    </details>
 95	    {% endif %}
 96	  </section>
 97	  {% endfor %}
 98	</div>
 99	
100	<section class="section card pad">
101	  {% set lp = g.letsplay %}
102	  <h2>Летсплей на YouTube {% if lp %}{{ method_badge(lp.method) }}{% endif %}</h2>
103	  {% if not lp %}
104	    <p class="muted">Поиск летсплея ещё не выполнялся.</p>
105	  {% elif not lp.video %}
106	    <p class="muted">{{ lp.note or 'Подходящий летсплей не найден.' }}</p>
107	  {% else %}
108	    {% set v = lp.video %}
109	    <div class="video">
110	      <div>
111	        <a class="thumb" href="https://www.youtube.com/watch?v={{ v.video_id|urlencode }}" target="_blank" rel="noopener noreferrer" title="Открыть на YouTube">
112	          <img src="https://i.ytimg.com/vi/{{ v.video_id|urlencode }}/hqdefault.jpg" alt="{{ v.title }}" loading="lazy" referrerpolicy="no-referrer">
113	          <span class="play"><span>▶</span></span>
114	        </a>
115	        <p class="small video-meta"><a href="https://www.youtube.com/watch?v={{ v.video_id|urlencode }}" target="_blank" rel="noopener noreferrer"><strong>{{ v.title }}</strong></a></p>
116	        <p class="small muted video-sub">{{ v.channel or '' }} · {{ v.views|num }} {{ v.views|plural('просмотр', 'просмотра', 'просмотров') }}{% if v.length_seconds %} · {{ v.length_seconds|duration }}{% endif %}</p>
117	      </div>
118	      <div>
119	        {% if lp.verdict %}<p class="verdict">{{ lp.verdict }}</p>{% endif %}
120	        {% if lp.summary %}<p class="lp-summary">{{ lp.summary }}</p>{% endif %}
121	        {% if lp.pros %}<h3>Понравилось блогеру</h3><ul class="points likes">{% for x in lp.pros %}<li>{{ x }}</li>{% endfor %}</ul>{% endif %}
122	        {% if lp.cons %}<h3>Не понравилось</h3><ul class="points dislikes">{% for x in lp.cons %}<li>{{ x }}</li>{% endfor %}</ul>{% endif %}
123	        {% if not lp.summary and not lp.pros and not lp.cons %}<p class="muted">{{ lp.note or 'Заключение построить не удалось.' }} Ссылка на ролик сохранена.</p>{% endif %}
124	        <div class="method">
125	          {% if lp.status == 'ok' and lp.transcript_method == 'whisper' %}{% set st = lp.stt or {} %}{% if lp.checked %}Субтитры YouTube недоступны{% else %}Субтитры YouTube отключены настройкой{% endif %}, поэтому речь блогера распознана локально моделью Whisper ({{ st.model or 'base' }}, faster-whisper на CPU) по первым {{ ((st.audio_seconds or 0) / 60)|round|int }} мин аудио ролика: {{ lp.transcript_chars|num }} символов, язык: {{ lp.transcript_lang }}, распознавание заняло {{ (st.transcribe_seconds or 0)|round|int }} с.
126	          {% elif lp.status == 'ok' %}Основано на расшифровке речи блогера из субтитров YouTube ({{ lp.transcript_chars|num }} символов, язык: {{ lp.transcript_lang }}).
127	          {% elif lp.note %}{{ lp.note }}.{% endif %}
128	          {% set skipped = (lp.stt_checked or [])|selectattr('video_id', 'defined')|list %}{% if lp.transcript_method == 'whisper' and skipped %}Ролик выбран из поиска YouTube по просмотрам: это самый популярный подходящий ролик с речью блогера, более популярные ({{ skipped|length }}) пропущены, потому что речь в них распознать не удалось (нет комментариев или аудио недоступно).{% else %}Самый популярный подходящий ролик выбран из поиска YouTube по просмотрам.{% endif %} Обновлено {{ lp.updated_at|dt }}.
129	          {% if lp.last_error %}<br><span class="badge err">последняя проверка: {{ lp.last_error }}</span>{% endif %}
130	          {% if lp.error %}<br><span class="badge err">LLM: {{ lp.error }}</span>{% endif %}
131	        </div>
132	      </div>
133	    </div>
134	    {% if lp.transcript_excerpt %}
135	    <details>
136	      <summary>{% if lp.transcript_method == 'whisper' %}Фрагменты речи блогера, распознанной Whisper{% else %}Фрагменты расшифровки речи блогера{% endif %} (начало, середина, конец)</summary>
137	      <p class="small desc excerpt">{{ lp.transcript_excerpt }}</p>
138	    </details>
139	    {% endif %}
140	    {% if lp.candidates and lp.candidates|length > 1 %}
141	    <details>
142	      <summary>Другие найденные ролики ({{ lp.candidates|length - 1 }})</summary>
143	      <ul class="quotes">
144	        {% for c in lp.candidates if c.video_id != v.video_id %}
145	        <li><a href="https://www.youtube.com/watch?v={{ c.video_id|urlencode }}" target="_blank" rel="noopener noreferrer">{{ c.title }}</a> · {{ c.channel }} · {{ c.views|num }} {{ c.views|plural('просмотр', 'просмотра', 'просмотров') }}</li>
146	        {% endfor %}
147	      </ul>
148	    </details>
149	    {% endif %}
150	  {% endif %}
151	</section>
152	
153	<section class="section card pad">
154	  <h2>Похожие игры <span class="muted small">из тех, что уже есть в базе</span></h2>
155	  {% if g.similar_games %}
156	  <div class="similar">
157	    {% for s in g.similar_games %}
158	    <a href="/game/{{ s.slug|urlencode }}">
159	      {{ cover(s.cover_url, s.title) }}
160	      <span class="sim-title">{{ s.title }}</span>
161	      <span class="chips">{{ meta_badge(s.metascore) }}{% for r in s.reasons[:2] %}<span class="chip">{{ r }}</span>{% endfor %}</span>
162	    </a>
163	    {% endfor %}
164	  </div>
165	  {% else %}
166	  <p class="muted">Похожих игр в базе пока нет. Список пересчитывается после каждой обработки.</p>
167	  {% endif %}
168	</section>
169	
170	<p class="small muted section">Первое появление в базе: {{ g.first_seen_at|dt }} · последнее обновление: {{ g.updated_at|dt }} · обработок: {{ g.times_processed }} · источник: {{ g.source }}</p>
171	{% endblock %}

  1	{% extends "base.html" %}
  2	{% block title %}Мониторинг · Игры Metacritic{% endblock %}
  3	{% block content %}
  4	{% set m = st.manual %}
  5	<div class="page-head">
  6	  <div>
  7	    <h1>Мониторинг сервиса</h1>
  8	    <p class="muted">Обработка запускается каждые {{ st.config.interval_minutes }} мин, за раз до {{ st.config.batch_size }} игр, не дольше {{ st.config.run_max_minutes }} мин. Страница обновляется в реальном времени.</p>
  9	  </div>
 10	  <form method="post" action="/run" id="run-form" class="run-box" data-available-at="{{ m.available_at or '' }}" data-code="{{ m.code }}" data-runs-today="{{ m.runs_today }}" data-daily-cap="{{ m.daily_cap }}" data-cooldown="{{ m.cooldown_seconds }}" data-retry-after="{{ m.retry_after }}" data-reason="{{ m.reason }}">
 11	    <button class="btn" type="submit" id="run-btn" {% if not m.allowed %}disabled{% endif %}>
 12	      {%- if m.code == 'busy' %}Обработка идёт…{% elif m.code == 'cooldown' %}Запуск через {{ m.retry_after|wait }}{% elif m.code == 'cap' %}Лимит ручных запусков на сегодня{% else %}Запустить обработку сейчас{% endif -%}
 13	    </button>
 14	    <span class="run-hint" id="run-hint">{% if m.code in ('cooldown', 'cap') %}{{ m.reason }}{% else %}Ручных запусков сегодня: {{ m.runs_today }}{% if m.daily_cap %} из {{ m.daily_cap }}{% endif %}. После каждого запуска пауза {{ (m.cooldown_seconds // 60) }} мин.{% endif %}</span>
 15	  </form>
 16	</div>
 17	
