from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(s):
        super().__init__(); s.out=[]; s.skip=0; s.inmain=False
    def handle_starttag(s,t,a):
        if t=='main': s.inmain=True
        if t in('script','style','select'): s.skip+=1
        if t in('p','div','li','tr','h1','h2','h3','section','br','summary','dt','details'): s.out.append('\n')
        if t in('td','dd','th'): s.out.append(' | ')
        if t=='span' and dict(a).get('class','').startswith('badge'): s.out.append(' [')
    def handle_endtag(s,t):
        if t in('script','style','select'): s.skip-=1
        if t=='main': s.inmain=False
        if t=='span': pass
    def handle_data(s,d):
        if s.inmain and not s.skip: s.out.append(d)
p=P(); p.feed(sys.stdin.read())
t=''.join(p.out); t=re.sub(r'[ \t]+',' ',t); t=re.sub(r'\n\s*\n+','\n',t)
print(t)
EOF
